/**
 * The wiki's Index: every page the reader can open, by folder, each with the opening of its text, when
 * it last changed and who changed it, and whether it needs checking because a page it cites changed
 * since. Generated by the node from what the reader can open; nothing writes to it. `?folder=` shows
 * one folder and what is under it.
 */
import { useCallback, useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { AppShell } from "@astryxdesign/core/AppShell";
import { Button } from "@astryxdesign/core/Button";
import { EmptyState } from "@astryxdesign/core/EmptyState";
import { HStack } from "@astryxdesign/core/HStack";
import { IconButton } from "@astryxdesign/core/IconButton";
import { List, ListItem } from "@astryxdesign/core/List";
import { Spinner } from "@astryxdesign/core/Spinner";
import { Heading, Text } from "@astryxdesign/core/Text";
import { ToggleButton } from "@astryxdesign/core/ToggleButton";
import { VStack } from "@astryxdesign/core/VStack";
import { ArrowLeft, BookOpen, CircleCheck, Database, FileText, ListFilter } from "lucide-react";
import { Wiki, type IndexEntry, type IndexSection, type WikiIndex } from "../api";
import { AppTopNav } from "../shell/AppTopNav";
import { LoadFailed } from "../ui/LoadFailed";
import { PageColumn } from "../ui/PageColumn";
import { absoluteTime, relativeTime } from "../lib/format";
import { tRich } from "../i18n/rich";
import { t } from "../i18n/i18n";
import { authorRefList, folderPathLabel } from "../wiki/names";
import { NeedsCheckingToken } from "../wiki/NeedsCheckingToken";
import { WikiTabs } from "../wiki/WikiTabs";

/** A section's heading: its folder's path, or what stands for a place with none. */
function sectionTitle(s: IndexSection): string {
  if (s.elsewhere) return t("pages.wiki.index.elsewhere");
  if (s.folder_id === null) return t("pages.wiki.index.topLevel");
  return folderPathLabel(s.path);
}

/** "Changed 3 days ago by Liv", the time with its date on hover. */
function changedLine(p: IndexEntry) {
  const time = (chunks: unknown[]) => (
    <time dateTime={p.changed_at} title={absoluteTime(p.changed_at)}>
      {chunks as never}
    </time>
  );
  return p.changed_by.length > 0
    ? tRich("pages.wiki.index.changedBy", { when: relativeTime(p.changed_at), names: authorRefList(p.changed_by), time })
    : tRich("pages.wiki.index.changed", { when: relativeTime(p.changed_at), time });
}

export default function WikiIndexPage() {
  const nav = useNavigate();
  const [params, setParams] = useSearchParams();
  const folder = params.get("folder");
  const [index, setIndex] = useState<WikiIndex | null>(null);
  const [failed, setFailed] = useState(false);
  const [checkingOnly, setCheckingOnly] = useState(false);

  const load = useCallback(() => {
    setFailed(false);
    setIndex(null);
    Wiki.index(folder ?? undefined).then(setIndex, () => setFailed(true));
  }, [folder]);
  useEffect(load, [load]);

  const needing = index?.sections.reduce((n, s) => n + s.pages.filter((p) => p.needs_checking).length, 0) ?? 0;
  const sections = (index?.sections ?? [])
    .map((s) => (checkingOnly ? { ...s, pages: s.pages.filter((p) => p.needs_checking) } : s))
    .filter((s) => s.pages.length > 0);
  const shownCount = index?.sections.reduce((n, s) => n + s.pages.length, 0) ?? 0;

  return (
    <AppShell topNav={<AppTopNav title={t("pages.wiki.index.title")} hasWorkspaceSwitcher />} contentPadding={0}>
      <PageColumn width={760}>
        <VStack gap={5}>
          <WikiTabs current="index" />
          <HStack gap={3} vAlign="center" justify="between" wrap="wrap">
            <Text color="secondary">{needing > 0 ? t("pages.wiki.index.checkingCount", { count: needing }) : t("pages.wiki.index.intro")}</Text>
            <HStack gap={2} vAlign="center">
              {folder && (
                <Button label={t("pages.wiki.index.wholeWiki")} variant="ghost" size="sm" icon={<ArrowLeft size={16} />} onClick={() => setParams({})} />
              )}
              {needing > 0 && (
                <ToggleButton
                  label={t("pages.wiki.index.checkingOnly")}
                  size="sm"
                  icon={<ListFilter size={16} />}
                  isPressed={checkingOnly}
                  onPressedChange={() => setCheckingOnly((on) => !on)}
                />
              )}
            </HStack>
          </HStack>
          {failed ? (
            <LoadFailed icon={<BookOpen size={24} />} title={t("pages.wiki.index.loadFailed")} onRetry={load} />
          ) : index === null ? (
            <VStack gap={2} hAlign="center" padding={6}>
              <Spinner label={t("pages.wiki.index.loading")} />
            </VStack>
          ) : sections.length === 0 ? (
            checkingOnly ? (
              <EmptyState icon={<CircleCheck size={28} />} title={t("pages.wiki.index.allCheckedTitle")} description={t("pages.wiki.index.allCheckedNote")} />
            ) : (
              <EmptyState icon={<BookOpen size={28} />} title={t("pages.wiki.index.emptyTitle")} description={t("pages.wiki.index.emptyNote")} />
            )
          ) : (
            <VStack gap={6}>
              {sections.map((s) => {
                const title = sectionTitle(s);
                return (
                  <List
                    key={s.elsewhere ? "elsewhere" : (s.folder_id ?? "top")}
                    hasDividers
                    density="balanced"
                    header={
                      <HStack gap={2} vAlign="center" justify="between">
                        <Heading level={2}>{title}</Heading>
                        {s.folder_id && !folder && (
                          <IconButton
                            label={t("pages.wiki.index.openFolder", { folder: title })}
                            variant="ghost"
                            size="sm"
                            icon={<ListFilter size={16} />}
                            onClick={() => setParams({ folder: s.folder_id! })}
                          />
                        )}
                      </HStack>
                    }
                  >
                    {s.pages.map((p) => (
                      <ListItem
                        key={p.doc_id}
                        label={p.title || t("common.untitled")}
                        startContent={p.doc_type === "database" ? <Database size={16} aria-hidden="true" /> : <FileText size={16} aria-hidden="true" />}
                        onClick={() => nav(`/doc/${p.doc_id}`)}
                        description={
                          <VStack gap={1}>
                            {p.needs_checking && (
                              <HStack>
                                <NeedsCheckingToken />
                              </HStack>
                            )}
                            {p.summary && (
                              <Text color="secondary" maxLines={2}>
                                {p.summary}
                              </Text>
                            )}
                            <Text type="supporting" color="secondary">
                              {changedLine(p)}
                            </Text>
                          </VStack>
                        }
                      />
                    ))}
                  </List>
                );
              })}
              {index.truncated && (
                <Text type="supporting" color="secondary">
                  {t("pages.wiki.index.truncated", { count: shownCount })}
                </Text>
              )}
            </VStack>
          )}
        </VStack>
      </PageColumn>
    </AppShell>
  );
}
